 -- Source roof7..9 py0..11; four dark eave pixels stay a vertical fascia.
 for x=59,64 do for sy=7,9 do local stop=sy==9 and .75 or 1;local a,b=(sy-7)/2.75,(sy-7+stop)/2.75
  quad({x,cap,7+a*5},{x+1,cap,7+a*5},{x+1,cap,7+b*5},{x,cap,7+b*5},uv(cells[x..','..sy].mid,'over',0,0,1,stop),{0,1,0},'cutoutOver')
 end
  quad({x,cap,12},{x+1,cap,12},{x+1,top,12},{x,top,12},uv(cells[x..',9'].mid,'over',0,.75,1,1),{0,0,1},'cutoutOver')
 end
 -- Native brick interior/base donor, tiled horizontally; symmetric hidden back.
 local wall=uv(101,'under',4/16,0,12/16,1)
 for x=59,64 do
  quad({x,top,7},{x+1,top,7},{x+1,base,7},{x,base,7},wall,{0,0,-1},'opaque')
  -- Hidden rear eave closes the same quarter-cell join as both side eaves.
  -- Reuse the exact native continuous outline row, without adding windows.
  quad({x,cap,7},{x+1,cap,7},{x+1,top,7},{x,top,7},uv(77,'over',0,11/16,1,12/16),{0,0,-1},'cutoutOver')
 end
 -- Authored Route12 style, native pixels at 16px per world cell.
 -- Each outward-facing facade uses its own reading direction; doors stay z10.5.
 for _,west in ipairs{true,false}do
  local plane=west and 59 or 65;local n={west and -1 or 1,0,0}
  local center=west and 3.5 or 1.5
  local function face(u0,u1,hi,lo,mid,ly,a,b,c,d,inset)
   local x=plane+(west and 1 or -1)*(inset or 0)+(ly=='over'and(west and -.002 or .002)or 0)
   local z0,z1=west and 7+u0 or 12-u0,west and 7+u1 or 12-u1
   quad({x,hi,z0},{x,hi,z1},{x,lo,z1},{x,lo,z0},uv(mid,ly,a,b,c,d),n,ly=='over'and'cutoutOver'or'opaque',glass(mid,ly))
  end
  -- Half-cell posts, four one-cell glass/brick header panels.
  for _,p in ipairs{{0,.5,438,0,.5},{4.5,5,439,.5,1}}do
   for _,ly in ipairs{'under','over'}do face(p[1],p[2],top,top-1,p[3],ly,p[4],0,p[5],1)end
  end
  for i=0,3 do for _,ly in ipairs{'under','over'}do face(.5+i,1.5+i,top,top-1,437,ly,0,0,1,1)end end
  -- Original outer gray posts continue down the two lower source rows.
  for _,p in ipairs{{0,.5,92,100,0,.5},{4.5,5,94,102,.5,1}}do
   face(p[1],p[2],top-1,top-2,p[3],'under',p[5],0,p[6],1)
   face(p[1],p[2],top-2,base,p[4],'under',p[5],0,p[6],1)
  end
  -- Plain native brick at quarter-cell density fills the non-door side.
  local fa,fb=west and .5 or 2.5,west and 2.5 or 4.5
  for u=fa,fb-.01,.5 do for row=0,7 do
   face(u,u+.5,base+(row+1)/4,base+row/4,437,'under',0,12/16,.5,1)
  end end
  -- The original two-cell closed door/canopy, without horizontal/vertical squeeze.

  for row,mids in ipairs{{392,393,394},{400,401,402}}do
   for _,p in ipairs{{center-1,center-.5,mids[1],.5,1},{center-.5,center+.5,mids[2],0,1},{center+.5,center+1,mids[3],0,.5}}do
    local hi,lo=top-row,top-row-1
    if row==1 then
     -- Lower three pixels of the upper door row join the recessed lower row.
     for _,ly in ipairs{'under','over'}do if ly=='under'or atlas.hasOver(p[3])then
      face(p[1],p[2],hi,base+1.1875,p[3],ly,p[4],0,p[5],13/16)
      face(p[1],p[2],base+1.1875,lo,p[3],ly,p[4],13/16,p[5],1,.12)
     end end
    else face(p[1],p[2],hi,lo,p[3],'under',p[4],0,p[5],1,.12)end
   end
  end
  -- Gray native opening boundary returns, following approved painted-door semantics.
  local r=uv(400,'under',7.5/16,4.5/16,7.5/16,4.5/16)
  local function P(u,y,depth)return{plane+(west and 1 or -1)*depth,y,west and 7+u or 12-u}end
  for _,u in ipairs{center-1,center+1}do
   quad(P(u,base,0),P(u,base,.12),P(u,base+1.1875,.12),P(u,base+1.1875,0),r,{0,0,u<center and(west and 1 or -1)or(west and -1 or 1)},'opaque')
  end
  quad(P(center-1,base+1.1875,0),P(center+1,base+1.1875,0),P(center+1,base+1.1875,.12),P(center-1,base+1.1875,.12),r,{0,-1,0},'opaque')
  -- Native continuous outline closes each cap/entry join.
  for z=7,11 do quad({plane,cap,z},{plane,cap,z+1},{plane,top,z+1},{plane,top,z},uv(77,'over',0,11/16,1,12/16),n,'cutoutOver')end
 end
 -- Native mixed side roof shoulders: OVER alpha owns only roof pixels;
 -- original UNDER ground/fence remains its native producer.
 for _,x in ipairs{58,65}do for sy=8,9 do local c=cells[x..','..sy];local stop=sy==9 and .75 or 1
  local a,b=(sy-7)/2.75,(sy-7+stop)/2.75
  quad({x,cap,7+a*5},{x+1,cap,7+a*5},{x+1,cap,7+b*5},{x,cap,7+b*5},uv(c.mid,'over',0,0,1,stop),{0,1,0},'cutoutOver')
  if sy==9 then quad({x,cap,12},{x+1,cap,12},{x+1,top,12},{x,top,12},uv(c.mid,'over',0,.75,1,1),{0,0,1},'cutoutOver')end
 end end
 out.stats={bounds={59,7,65,12},wallRows=3,bodyTop=top,roofTop=cap,sideOpenings={{59,10,11},{65,10,11}},
  reconstruction='native source five-cell depth, flat ribbed cap, native brick hidden sides/back; Route12 authored three-row appearance on both E/W entrances, native footprint/support and mixed OVER shoulders retained'}
 return out
end
G.spec=spec
return G
